            return C ?
                <C {...this.props} />
                :
                <Box style={{display: "flex", alignItems: "center", justifyContent: "center", width: "100%", height: "100%", minHeight: "250px"}}>
                    <Loader/>
                </Box>

        }
    }

    return AsyncComponent;
}"}

